// Extrair dados da mensagem jurídica do WhatsApp
const entry = $input.all()[0].json.entry?.[0];
const change = entry?.changes?.[0];
const message = change?.value?.messages?.[0];
const contact = change?.value?.contacts?.[0];

const phoneNumber = message?.from;
const contactName = contact?.profile?.name || 'Cliente';
const messageId = message?.id;
const timestamp = message?.timestamp;

// Verificar tipo de mensagem
const messageType = message?.type;
let messageContent = '';
let mediaUrl = '';
let mediaType = '';

if (messageType === 'text') {
  messageContent = message?.text?.body || '';
} else if (messageType === 'audio') {
  mediaUrl = message?.audio?.id;
  mediaType = 'audio';
  messageContent = '[Áudio recebido - Consulta jurídica]';
} else if (messageType === 'image') {
  mediaUrl = message?.image?.id;
  mediaType = 'image';
  messageContent = message?.image?.caption || '[Documento jurídico recebido]';
} else if (messageType === 'document') {
  mediaUrl = message?.document?.id;
  mediaType = 'document';
  messageContent = message?.document?.caption || '[Documento jurídico anexado]';
}

// Verificar se é uma mensagem válida
if (!phoneNumber) {
  return [{
    json: {
      error: 'Mensagem inválida - sem telefone',
      phoneNumber,
      messageContent
    }
  }];
}

// Preparar dados para processamento jurídico
return [{
  json: {
    phoneNumber: phoneNumber,
    contactName: contactName,
    messageId: messageId,
    timestamp: timestamp,
    messageType: messageType,
    messageContent: messageContent,
    mediaUrl: mediaUrl,
    mediaType: mediaType,
    processedAt: new Date().toISOString(),
    platform: 'whatsapp-dra-julia'
  }
}];

// Combinar resultados de análise jurídica
const dadosOriginais = $('Processar Mensagem Jurídica').item.json;
let textoProcessado = '';
let analiseDocumento = '';
let audioTranscrito = '';

// Verificar se houve transcrição de áudio
if ($input.all().some(item => item.json.text)) {
  audioTranscrito = $input.all().find(item => item.json.text)?.json.text || '';
  textoProcessado = audioTranscrito;
}

// Verificar se houve análise de documento
if ($input.all().some(item => item.json.choices)) {
  const analiseResult = $input.all().find(item => item.json.choices);
  if (analiseResult) {
    analiseDocumento = analiseResult.json.choices[0]?.message?.content || '';
    textoProcessado = analiseDocumento;
  }
}

// Se é texto normal, usar o conteúdo original
if (!textoProcessado && dadosOriginais.messageType === 'text') {
  textoProcessado = dadosOriginais.messageContent;
}

// Identificar área jurídica baseada no conteúdo
let areaJuridica = 'Geral';
const conteudo = textoProcessado.toLowerCase();

if (conteudo.includes('contrato') || conteudo.includes('empresa') || conteudo.includes('cnpj')) {
  areaJuridica = 'Direito Empresarial';
} else if (conteudo.includes('trabalho') || conteudo.includes('clt') || conteudo.includes('rescisão')) {
  areaJuridica = 'Direito Trabalhista';
} else if (conteudo.includes('família') || conteudo.includes('divórcio') || conteudo.includes('pensão')) {
  areaJuridica = 'Direito de Família';
} else if (conteudo.includes('imóvel') || conteudo.includes('casa') || conteudo.includes('terreno')) {
  areaJuridica = 'Direito Imobiliário';
} else if (conteudo.includes('processo') || conteudo.includes('tribunal') || conteudo.includes('juiz')) {
  areaJuridica = 'Direito Processual';
} else if (conteudo.includes('crime') || conteudo.includes('polícia') || conteudo.includes('prisão')) {
  areaJuridica = 'Direito Criminal';
}

return [{
  json: {
    ...dadosOriginais,
    textoProcessado: textoProcessado,
    analiseDocumento: analiseDocumento,
    audioTranscrito: audioTranscrito,
    areaJuridica: areaJuridica,
    temAnalise: !!(analiseDocumento || audioTranscrito)
  }
}];

// Processar solicitação de geração de documento
const response = $input.all()[0].json.choices?.[0]?.message?.content;
const dadosOriginais = $('Combinar Resultados Jurídicos').item.json;

if (response && response.includes('GERAR_DOCUMENTO')) {
  // Extrair dados do formato: GERAR_DOCUMENTO|TIPO|DETALHES
  const parts = response.split('|');

  if (parts.length >= 3) {
    const tipoDocumento = parts[1].trim();
    const detalhes = parts[2].trim();

    return [{
      json: {
        ...dadosOriginais,
        documento: {
          tipo: tipoDocumento,
          detalhes: detalhes,
          solicitadoEm: new Date().toISOString(),
          status: 'Em elaboração',
          cliente: dadosOriginais.contactName,
          telefone: dadosOriginais.phoneNumber
        },
        originalResponse: response
      }
    }];
  }
}

return [{
  json: {
    ...dadosOriginais,
    originalResponse: response,
    isDocumento: false
  }
}];

