// Processar agendamento de consulta
const response = $input.all()[0].json.choices?.[0]?.message?.content;
const dadosOriginais = $('Combinar Resultados Jurídicos').item.json;

if (response && response.includes('AGENDAR_CONSULTA')) {
  // Extrair dados do formato: AGENDAR_CONSULTA|NOME|TELEFONE|AREA|DATA_PREFERIDA
  const parts = response.split('|');

  if (parts.length >= 5) {
    const nome = parts[1].trim();
    const telefone = parts[2].trim();
    const area = parts[3].trim();
    const dataPreferida = parts[4].trim();

    // Calcular data/hora da consulta (próximo dia útil às 14h como padrão)
    const agora = new Date();
    const proximoDiaUtil = new Date(agora);
    proximoDiaUtil.setDate(proximoDiaUtil.getDate() + 1);
    proximoDiaUtil.setHours(14, 0, 0, 0);

    const fimConsulta = new Date(proximoDiaUtil.getTime() + (60 * 60 * 1000)); // 1 hora depois

    return [{
      json: {
        ...dadosOriginais,
        consulta: {
          nome: nome,
          telefone: telefone,
          area: area,
          dataPreferida: dataPreferida,
          dataAgendada: proximoDiaUtil.toISOString(),
          dataFim: fimConsulta.toISOString(),
          titulo: `Consulta Jurídica - ${nome} (${area})`,
          descricao: `Consulta jurídica agendada\nCliente: ${nome}\nTelefone: ${telefone}\nÁrea: ${area}\nData preferida: ${dataPreferida}\nStatus: Agendada\nPlataforma: WhatsApp Dra. Júlia`,
          status: 'Agendada'
        },
        originalResponse: response
      }
    }];
  }
}

return [{
  json: {
    ...dadosOriginais,
    originalResponse: response,
    isConsulta: false
  }
}];

// Filtrar consultas jurídicas para hoje
const hoje = new Date();
hoje.setHours(0, 0, 0, 0);
const amanha = new Date(hoje);
amanha.setDate(amanha.getDate() + 1);

const eventos = $input.all()[0].json;
const consultasHoje = [];

if (eventos && Array.isArray(eventos)) {
  eventos.forEach(evento => {
    if (evento.start) {
      const dataConsulta = new Date(evento.start.dateTime || evento.start.date);
      dataConsulta.setHours(0, 0, 0, 0);

      // Se a consulta é para hoje
      if (dataConsulta.getTime() === hoje.getTime()) {
        // Extrair telefone da descrição
        const descricao = evento.description || '';
        const telefoneMatch = descricao.match(/Telefone: ([+\d\s\-\(\)]+)/);

        if (telefoneMatch) {
          consultasHoje.push({
            titulo: evento.summary,
            inicio: evento.start.dateTime || evento.start.date,
            telefone: telefoneMatch[1].trim(),
            descricao: descricao
          });
        }
      }
    }
  });
}

return consultasHoje.map(consulta => ({ json: consulta }));
